<script setup lang="tsx">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { NTag } from 'naive-ui'; import { fetchApp, fetchReleases } from '@/service/api'; import type { AndroidApp, AndroidRelease } from '@/service/api/app-publish';
const route = useRoute(); const id = computed(() => Number(route.params.id)); const app = ref<AndroidApp>(); const releases = ref<AndroidRelease[]>([]); const loading = ref(false); const serviceBaseUrl = import.meta.env.VITE_SERVICE_BASE_URL;
const columns = [{ title: '版本', key: 'versionName', render: (r: AndroidRelease) => <div class="version-cell"><b>{r.versionName}</b><code>code {r.versionCode} · build {r.buildNo}</code></div> }, { title: '更新方式', key: 'updateMode', width: 120, render: (r: AndroidRelease) => <NTag type={r.updateMode === 'FORCE' ? 'error' : r.updateMode === 'SILENT' ? 'warning' : 'info'}>{({ NORMAL: '普通', FORCE: '强制', SILENT: '静默' } as any)[r.updateMode] || r.updateMode}</NTag> }, { title: '大小', key: 'fileSize', width: 100, render: (r: AndroidRelease) => `${(r.fileSize / 1024 / 1024).toFixed(1)} MB` }, { title: '下载', key: 'downloadCount', width: 90 }, { title: '上传时间', key: 'createdAt', width: 170, render: (r: AndroidRelease) => new Date(r.createdAt).toLocaleString() }, { title: '', key: 'action', width: 90, render: (r: AndroidRelease) => <a class="download-link" href={`${import.meta.env.VITE_SERVICE_BASE_URL}/download/releases/${r.id}`}>下载</a> }];
async function load() { loading.value = true; const [a, r] = await Promise.all([fetchApp(id.value), fetchReleases(id.value, { page: 1, size: 100 })]); if (!a.error) app.value = a.data; if (!r.error) releases.value = r.data.records; loading.value = false; } onMounted(load);
</script>
<template><NSpace vertical :size="16"><NCard :bordered="false"><div class="app-hero"><div class="app-icon"><img v-if="app?.iconUrl" :src="app.iconUrl" :alt="app.appName" /><template v-else>{{ app?.appName?.slice(0,1) }}</template></div><div><p>ANDROID APPLICATION</p><h2>{{ app?.appName || '加载中' }}</h2><code>{{ app?.packageName }}</code></div><div class="hero-actions"><NTag :type="app?.status === 'ENABLED' ? 'success' : 'default'" round>{{ app?.status === 'ENABLED' ? '运行中' : '已停用' }}</NTag><NButton type="primary" tag="a" :href="`${serviceBaseUrl}/download/apps/${app?.packageName}/latest`">下载最新版</NButton></div></div></NCard><NCard title="版本档案" :bordered="false"><NDataTable :columns="columns" :data="releases" :loading="loading" :row-key="r => r.id"/></NCard></NSpace></template>
<style scoped>.app-hero{display:grid;grid-template-columns:72px 1fr auto;align-items:center;gap:18px}.app-icon{display:grid;width:68px;height:68px;overflow:hidden;place-items:center;border-radius:18px;background:#17211b;color:#b8f34a;font-size:28px;font-weight:800}.app-icon img{width:100%;height:100%;object-fit:cover}.app-hero p{margin:0;color:#6f8376;font:700 10px ui-monospace,monospace;letter-spacing:.16em}.app-hero h2{margin:5px 0;font-size:26px}.app-hero code{color:#708077}.hero-actions{display:flex;align-items:center;gap:12px}:deep(.version-cell){display:flex;flex-direction:column;gap:4px}:deep(.version-cell code){color:#859188;font-size:11px}@media(max-width:650px){.app-hero{grid-template-columns:60px 1fr}.hero-actions{grid-column:1/-1}}</style>
